"""Pixel pattern generated by rtl/pix_source.v (on-chip frame source, roadmap 1.10).

Frame f: a 24x24 bright square (200) whose top-left corner is at (3*f mod 128, 2*f mod 128),
wrapping around the frame, on a static horizontal gradient 40 + (x >> 2).
"""
import numpy as np

SQ = 24
FG = 200


def pattern_frame(f, size=128):
    y, x = np.mgrid[0:size, 0:size]
    sx, sy = (3 * f) & 127, (2 * f) & 127
    inside = (((x - sx) & 127) < SQ) & (((y - sy) & 127) < SQ)
    return np.where(inside, FG, 40 + (x >> 2)).astype(np.uint8)
